import AxeBuilder from "@axe-core/playwright";
import { chromium } from "@playwright/test";

const applicationUrl = process.argv[2];

if (!applicationUrl) {
  throw new Error(
    "The application URL is required for the acceptance journey."
  );
}

const JOURNEY_VIEWPORT = { height: 844, width: 390 };
const NARROW_VIEWPORTS = [375, 430];
const MAX_NATIVE_CONTROL_TABS = 4;
const MINIMUM_TARGET_SIZE = 44;
const INITIAL_SIGHTING_PATTERN = /August 10, 2026 at 10:00 AM/;
const CORRECTED_SIGHTING_PATTERN = /August 17, 2026 at 2:15 PM/;
const FAILURE_SIGHTING_PATTERN = /August 24, 2026 at 12:00 PM/;
const DONENESS_FAILURE_PATTERN = /Unable to save doneness/;

function ensure(condition, message) {
  if (!condition) {
    throw new Error(message);
  }
}

function describeViewport(viewport) {
  return `${viewport.width}x${viewport.height}`;
}

async function expectVisible(locator, description) {
  await locator.waitFor({ state: "visible" });
  ensure(await locator.isVisible(), `${description} is visible`);
}

async function assertNoHorizontalOverflow(page, description) {
  const dimensions = await page.evaluate(() => ({
    clientWidth: document.documentElement.clientWidth,
    scrollWidth: document.documentElement.scrollWidth,
  }));

  ensure(
    dimensions.scrollWidth <= dimensions.clientWidth,
    `${description} does not overflow horizontally (${dimensions.scrollWidth}px > ${dimensions.clientWidth}px)`
  );
}

async function assertTouchTargets(page, description) {
  const undersizedTargets = await page
    .locator("a, button, input, select")
    .evaluateAll(
      (elements, minimumTargetSize) =>
        elements.flatMap((element) => {
          const rectangle = element.getBoundingClientRect();
          const name =
            element.getAttribute("aria-label") ||
            element.textContent?.trim() ||
            element.getAttribute("id") ||
            element.tagName.toLowerCase();

          return rectangle.width >= minimumTargetSize &&
            rectangle.height >= minimumTargetSize
            ? []
            : [
                {
                  height: Math.round(rectangle.height),
                  name,
                  width: Math.round(rectangle.width),
                },
              ];
        }),
      MINIMUM_TARGET_SIZE
    );

  ensure(
    undersizedTargets.length === 0,
    `${description} has an interactive target below ${MINIMUM_TARGET_SIZE}px: ${JSON.stringify(undersizedTargets)}`
  );
}

async function assertAccessibility(page, description) {
  const results = await new AxeBuilder({ page }).analyze();
  const blockingViolations = results.violations.filter(
    (violation) =>
      violation.impact === "critical" || violation.impact === "serious"
  );

  ensure(
    blockingViolations.length === 0,
    `${description} has serious or critical axe violations: ${JSON.stringify(blockingViolations)}`
  );

  await assertNoHorizontalOverflow(page, description);
  await assertTouchTargets(page, description);
}

async function openCapture(page) {
  await page.goto(applicationUrl, { waitUntil: "networkidle" });
  await expectVisible(
    page.getByRole("heading", { name: "Capture" }),
    "Capture heading"
  );
}

async function saveSighting(page, labelDate, labelTime) {
  await page.locator("#label-date").fill(labelDate);
  await page.locator("#label-time").fill(labelTime);
  await page.getByRole("button", { name: "Save label time" }).click();
  await expectVisible(
    page.getByRole("heading", { name: "Sighting saved" }),
    "completion heading"
  );
}

async function assertFocused(locator, description) {
  await locator.waitFor({ state: "visible" });
  const isFocused = await locator.evaluate(
    (element) => document.activeElement === element
  );
  ensure(isFocused, `${description} receives focus`);
}

async function pressUntilFocused(page, locator, key, description) {
  for (
    let pressCount = 0;
    pressCount < MAX_NATIVE_CONTROL_TABS;
    pressCount += 1
  ) {
    await page.keyboard.press(key);
    const isFocused = await locator.evaluate(
      (element) => document.activeElement === element
    );

    if (isFocused) {
      return;
    }
  }

  await assertFocused(locator, description);
}

async function runFullJourney(page) {
  await openCapture(page);
  await expectVisible(page.getByRole("main"), "main landmark");
  await expectVisible(
    page.getByRole("navigation", { name: "Primary navigation" }),
    "navigation"
  );
  await expectVisible(page.locator("#label-time"), "labelled time input");
  await expectVisible(page.locator("#label-date"), "labelled date input");
  await assertAccessibility(page, "initial Capture at 390px");

  await page.locator("#label-time").focus();
  await assertFocused(page.locator("#label-time"), "Capture label-time input");
  await pressUntilFocused(
    page,
    page.locator("#label-date"),
    "Tab",
    "Capture label-date input after Tab"
  );
  await pressUntilFocused(
    page,
    page.locator("#label-time"),
    "Shift+Tab",
    "Capture label-time input after Shift+Tab"
  );
  await page.locator("#label-date").fill("2026-08-10");
  await page.locator("#label-time").fill("10:00");
  await page.locator("#label-time").focus();
  await page.keyboard.press("Enter");
  await expectVisible(
    page.getByRole("heading", { name: "Sighting saved" }),
    "completion heading after keyboard submit"
  );
  await assertFocused(
    page.getByRole("heading", { name: "Sighting saved" }),
    "completion heading"
  );
  await assertAccessibility(page, "completion at 390px");

  await page.reload({ waitUntil: "networkidle" });
  await expectVisible(
    page.getByRole("heading", { name: "Capture" }),
    "Capture after reload"
  );
  const persistedSighting = page.getByRole("button", {
    name: INITIAL_SIGHTING_PATTERN,
  });
  await expectVisible(
    persistedSighting,
    "recent sighting after reload before enrichment"
  );
  await persistedSighting.click();
  await expectVisible(
    page.getByRole("heading", { name: "Correct sighting" }),
    "correction heading"
  );
  await assertFocused(
    page.getByRole("heading", { name: "Correct sighting" }),
    "correction heading"
  );
  await assertAccessibility(page, "correction at 390px");
  await page.getByRole("button", { name: "Cancel" }).click();
  await expectVisible(
    page.getByRole("heading", { name: "Capture" }),
    "Capture after cancel"
  );

  await saveSighting(page, "2026-08-17", "14:05");
  await page.getByRole("button", { name: "Medium" }).focus();
  await assertFocused(
    page.getByRole("button", { name: "Medium" }),
    "Medium doneness button"
  );
  await page.keyboard.press("Space");
  await expectVisible(
    page.getByText("Doneness saved as medium."),
    "doneness status"
  );
  await page.getByRole("button", { name: "Correct this sighting" }).click();
  await expectVisible(
    page.getByRole("heading", { name: "Correct sighting" }),
    "completion correction"
  );
  await page.getByLabel("Label time").fill("14:15");
  await page.getByLabel("Doneness").selectOption("dark");
  await page.getByRole("button", { name: "Save correction" }).focus();
  await page.keyboard.press("Enter");
  await expectVisible(
    page.getByRole("heading", { name: "Sighting saved" }),
    "completion after correction"
  );
  await expectVisible(
    page.getByText(CORRECTED_SIGHTING_PATTERN),
    "corrected label time"
  );
  await page.getByRole("button", { exact: true, name: "Done" }).click();
  await expectVisible(
    page.getByRole("heading", { name: "Capture" }),
    "Capture after Done"
    "Capture after Done"
  );
  ensure(
    !new URL(page.url()).searchParams.has("completion"),
    "Done removes the completion recovery URL"
  );

  await expectVisible(
    page.getByRole("heading", { name: "Recent Sightings" }),
    "recent heading"
  );
  await page.getByRole("button", { name: CORRECTED_SIGHTING_PATTERN }).click();
  await expectVisible(
    page.getByRole("heading", { name: "Correct sighting" }),
    "recent correction"
  );
  await page.getByRole("button", { name: "Delete sighting" }).click();
  await expectVisible(
    page.getByRole("heading", { name: "Permanently delete this sighting?" }),
    "deletion confirmation"
  );
  await assertFocused(
    page.getByRole("heading", { name: "Permanently delete this sighting?" }),
    "deletion confirmation heading"
  );
  await page.getByRole("button", { name: "Permanently delete" }).click();
  await expectVisible(
    page.getByRole("heading", { name: "Capture" }),
    "Capture after deletion"
  );
  ensure(
    (await page
      .getByRole("button", { name: CORRECTED_SIGHTING_PATTERN })
      .count()) === 0,
    "deleted sighting is absent from Recent Sightings"
  );

  await page.getByRole("link", { name: "Plan" }).focus();
  await assertFocused(page.getByRole("link", { name: "Plan" }), "Plan link");
  await page.keyboard.press("Enter");
  await expectVisible(
    page.getByRole("heading", { name: "Plan" }),
    "Plan heading"
  );
  await page.getByLabel("Weekday", { exact: true }).selectOption("2");
  await expectVisible(
    page.getByRole("heading", { name: "No history for this weekday" }),
    "no-weekday-history state"
  );
  await page.getByLabel("Weekday", { exact: true }).selectOption("1");
  await page.getByLabel("Approximate time").fill("10:00");
  await expectVisible(
    page.getByRole("heading", { name: "Not enough history to compare yet" }),
    "sparse Plan state"
  );
  await assertAccessibility(page, "Plan at 390px");

  await page
    .getByRole("navigation", { name: "Primary navigation" })
    .getByRole("link", { name: "Capture" })
    .click();
  await expectVisible(
    page.getByRole("heading", { name: "Capture" }),
    "Capture before failure case"
  );
  await saveSighting(page, "2026-08-24", "12:00");

  let interceptedEnrichment = false;
  await page.route("**/*", async (route) => {
    if (route.request().method() === "POST") {
      interceptedEnrichment = true;
      await route.abort("failed");
      return;
    }

    await route.continue();
  });
  await page.getByRole("button", { name: "Light" }).click();
  await expectVisible(
    page.getByText(DONENESS_FAILURE_PATTERN),
    "enrichment failure"
  );
  ensure(interceptedEnrichment, "enrichment request was intercepted");
  await page.unroute("**/*");
  await page.reload({ waitUntil: "networkidle" });
  await expectVisible(
    page.getByRole("heading", { name: "Capture" }),
    "Capture after enrichment failure"
  );
  await page.getByRole("button", { name: FAILURE_SIGHTING_PATTERN }).click();
  await expectVisible(
    page.getByRole("heading", { name: "Correct sighting" }),
    "correction after enrichment failure"
  );
}

async function assertNarrowViewports(browser) {
  for (const width of NARROW_VIEWPORTS) {
    const viewport = { height: 844, width };
    const context = await browser.newContext({ viewport });
    const page = await context.newPage();

    try {
      await openCapture(page);
      await assertAccessibility(
        page,
        `Capture at ${describeViewport(viewport)}`
      );
      await page.getByRole("link", { name: "Plan" }).click();
      await expectVisible(
        page.getByRole("heading", { name: "Plan" }),
        "Plan heading"
      );
      await assertAccessibility(page, `Plan at ${describeViewport(viewport)}`);
    } finally {
      await context.close();
    }
  }
}

const browser = await chromium.launch({
  executablePath: process.env.BROWSER_EXECUTABLE_PATH,
  headless: true,
});

try {
  const context = await browser.newContext({ viewport: JOURNEY_VIEWPORT });
  const page = await context.newPage();

  try {
    await runFullJourney(page);
  } finally {
    await context.close();
  }

  await assertNarrowViewports(browser);
  console.log(
    JSON.stringify({
      browser:
        process.env.ACCEPTANCE_BROWSER_LABEL ?? `Chromium ${browser.version()}`,
      result: "passed",
      viewports: [JOURNEY_VIEWPORT.width, ...NARROW_VIEWPORTS],
    })
  );
} finally {
  await browser.close();
}
#!/bin/sh

set -eu

IMAGE_TAG="${IMAGE_TAG:-chicken-tracking:smoke}"
NETWORK_NAME="chicken-tracking-smoke-$$"
DATABASE_NAME="chicken-tracking-database-$$"
APP_NAME="chicken-tracking-app-$$"
MIGRATION_NAME="chicken-tracking-migration-$$"
POSTGRES_URL="REDACTED"
APP_DATABASE_URL="REDACTED"
MIGRATION_LOCK_KEY="481849106705489314"

cleanup() {
  docker rm --force "$APP_NAME" "$MIGRATION_NAME" "$DATABASE_NAME" >/dev/null 2>&1 || true
  docker network rm "$NETWORK_NAME" >/dev/null 2>&1 || true
}

trap cleanup EXIT INT TERM

docker build --tag "$IMAGE_TAG" .
docker network create "$NETWORK_NAME" >/dev/null
docker run --detach --name "$DATABASE_NAME" --network "$NETWORK_NAME" \
  --env POSTGRES_DB=chicken_tracking \
  --env POSTGRES_PASSWORD=REDACTED \
  --env POSTGRES_USER=postgres \
  postgres:17-alpine >/dev/null

attempt=0
until docker logs "$DATABASE_NAME" 2>&1 \
  | grep --quiet "PostgreSQL init process complete; ready for start up."; do
  attempt=$((attempt + 1))
  if [ "$attempt" -ge 30 ]; then
    docker logs "$DATABASE_NAME" >&2
    echo "PostgreSQL did not finish initialization." >&2
    exit 1
  fi
  sleep 1
done

attempt=0
until docker exec "$DATABASE_NAME" psql --set ON_ERROR_STOP=1 --username postgres \
  --dbname chicken_tracking --command "SELECT 1" >/dev/null; do
  attempt=$((attempt + 1))
  if [ "$attempt" -ge 30 ]; then
    docker logs "$DATABASE_NAME" >&2
    echo "PostgreSQL did not become queryable." >&2
    exit 1
  fi
  sleep 1
done

POSTGRES_VERSION="$(docker exec "$DATABASE_NAME" psql --tuples-only --no-align \
  --username postgres --dbname chicken_tracking --command "SHOW server_version")"
echo "PostgreSQL server version: ${POSTGRES_VERSION} (postgres:17-alpine)"

docker exec "$DATABASE_NAME" psql --set ON_ERROR_STOP=1 --username postgres --dbname postgres \
  --command "CREATE ROLE chicken_tracking LOGIN PASSWORD 'chicken_tracking' NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT" \
  >/dev/null
docker exec "$DATABASE_NAME" psql --set ON_ERROR_STOP=1 --username postgres --dbname postgres \
  --command "ALTER DATABASE chicken_tracking OWNER TO chicken_tracking" >/dev/null

if docker run --rm "$IMAGE_TAG"; then
  echo "Container unexpectedly served without DATABASE_URL." >&2
  exit 1
fi

if docker run --rm --network "$NETWORK_NAME" \
  --env DATABASE_URL="REDACTED" \
  "$IMAGE_TAG"; then
  echo "Container unexpectedly served after a migration connection failure." >&2
  exit 1
fi

# Hold the same advisory lock to prove both a standalone migration and a serving container wait
# before they discover or apply the migration history. The two containers then race normally.
docker exec "$DATABASE_NAME" psql --set ON_ERROR_STOP=1 --username postgres \
  --dbname chicken_tracking --command "SELECT pg_advisory_lock(${MIGRATION_LOCK_KEY}); SELECT pg_sleep(3)" \
  >/dev/null &
LOCK_PROCESS_ID=$!
sleep 1

docker run --detach --name "$MIGRATION_NAME" --network "$NETWORK_NAME" \
  --env DATABASE_URL="$APP_DATABASE_URL" "$IMAGE_TAG" migrate >/dev/null
docker run --detach --name "$APP_NAME" --network "$NETWORK_NAME" \
  --publish 127.0.0.1::3000 --env DATABASE_URL="$APP_DATABASE_URL" "$IMAGE_TAG" >/dev/null

sleep 1
if docker exec "$DATABASE_NAME" psql --tuples-only --no-align --username postgres \
  --dbname chicken_tracking --command "SELECT to_regclass('drizzle.__drizzle_migrations') IS NOT NULL" \
  | grep --quiet true; then
  echo "Migration ran before the advisory lock was released." >&2
  exit 1
fi

wait "$LOCK_PROCESS_ID"

if [ "$(docker wait "$MIGRATION_NAME")" != "0" ]; then
  docker logs "$MIGRATION_NAME" >&2
  echo "Standalone migration failed while starting concurrently with the server." >&2
  exit 1
fi

attempt=0
until curl --fail --silent --show-error "http://127.0.0.1:$(docker port "$APP_NAME" 3000/tcp | sed 's/.*://')/health" \
  | grep --quiet '"status":"ok"'; do
  attempt=$((attempt + 1))
  if [ "$attempt" -ge 30 ]; then
    docker logs "$APP_NAME" >&2
    echo "Container did not become healthy." >&2
    exit 1
  fi
  sleep 1
done

APP_HTTP_PORT="$(docker port "$APP_NAME" 3000/tcp | sed 's/.*://')"
curl --fail --silent --show-error "http://127.0.0.1:${APP_HTTP_PORT}/" | grep --quiet "Capture"
curl --fail --silent --show-error "http://127.0.0.1:${APP_HTTP_PORT}/plan" | grep --quiet "Plan"

# Every acceptance journey starts from a fresh database but has a stable historical record. Its
# intentionally old creation instant keeps the journey's new sightings first in Recent Sightings.
docker exec "$DATABASE_NAME" psql --set ON_ERROR_STOP=1 --username postgres \
  --dbname chicken_tracking --command \
  "INSERT INTO sightings (label_date, label_minute, created_at, updated_at) VALUES ('2020-01-01', 600, '2000-01-01T00:00:00Z', '2000-01-01T00:00:00Z')" \
  >/dev/null
node ./scripts/acceptance-journey.mjs "http://127.0.0.1:${APP_HTTP_PORT}"

docker stop "$DATABASE_NAME" >/dev/null
if curl --fail --silent "http://127.0.0.1:${APP_HTTP_PORT}/health"; then
  echo "Health remained ready after PostgreSQL connectivity was removed." >&2
  exit 1
fi

echo "Container smoke check passed."
# MVP acceptance record — 2026-08-11

## Status

**Not accepted for final handoff.** The repository candidate has reproducible automated coverage,
but the required physical iPhone 15 Pro/current Safari run has not been performed. Neither a
desktop Chromium run nor viewport emulation is treated as evidence for that named requirement.

## Candidate

- Application source commit: `9131dfef7ce0a1b9cfba15f0526940f54ef2f111`
- Record date: 2026-08-11 (America/Chicago)
- Product scope: Capture, optional doneness, correction/cancel/delete/recent sightings, and
  Visit plan only. No history grid, history route, account, location, or multi-user feature ships.

## Reproducible commands and observed result

| Command | Result in this environment | Scope |
| --- | --- | --- |
| `bun install` | Passed with Bun 1.3.14 | Resolved and recorded `@axe-core/playwright` 4.13.0. |
| `bun run lint` | Passed | Repository lint gate. |
| `bun run typecheck` | Passed | Strict TypeScript. |
| `bunx vitest run` | Passed: 69 tests; 3 conditional migration tests skipped | Unit/route suite ran. The real-PostgreSQL integration suite was not selected because `DATABASE_URL` was absent. |
| `bun run build` | Passed | Production build completed; bundler emitted existing third-party directive/unused-import warnings only. |
| `bun run acceptance:container` | Passed in CI | [CI run 31520253627](https://github.com/chris-tse/costco-chicken-tracker/actions/runs/31520253627) ran the assembled container against PostgreSQL 17.10. Local Docker remains unavailable. |

`bun run acceptance:container` is the repeatable assembled gate. It builds the OCI image,
starts a disposable PostgreSQL 17 container, runs migration/startup/health checks, and invokes
`scripts/acceptance-journey.mjs` against the running image. It seeds one deterministic historical
record with an old creation instant, then runs axe, semantic and target checks, Tab/Shift+Tab/
Enter/Space keyboard checks, focus checks, horizontal-overflow checks, and the full Capture/Completion/
Correction/Recent/Plan journey at 375px, 390px, and 430px portrait widths. It also reloads before
enrichment and intercepts the doneness request to prove a failed enrichment leaves the created
sighting recoverable and correctable.

The `supported-chrome` CI job invoked that same resettable container gate separately with current
Chrome for Testing and with the immediately previous Chrome major. Both passed in CI run 31520253627.

## PostgreSQL and container evidence

- Acceptance database: isolated/resettable PostgreSQL 17.10 (`postgres:17-alpine`), created by
  `scripts/container-smoke.sh` and seeded with one deterministic historical record; no production
  or personal database is used. [CI run 31520253627](https://github.com/chris-tse/costco-chicken-tracker/actions/runs/31520253627)
  recorded the server version and passed the container smoke gate.
- Local result: not run because Docker and PostgreSQL tooling are unavailable.

## Device and browser evidence

| Requirement | Result | Evidence / limitation |
| --- | --- | --- |
| 375px, 390px, 430px portrait layout | Passed in CI | The acceptance script found no horizontal overflow and no targets under 44px at every width in CI run 31520253627. |
| Automated semantics, labels, headings, statuses, target, focus, and contrast checks | Passed in CI | Axe passed on Capture, Completion, Correction, and Plan; the journey also checked landmarks, labels, live status, and keyboard/focus behavior. |
| Current Chrome | Passed | Google Chrome for Testing 151.0.7922.77 ran the fresh container journey in [CI run 31520253627](https://github.com/chris-tse/costco-chicken-tracker/actions/runs/31520253627). |
| Immediately previous Chrome major | Passed | Google Chrome for Testing 150.0.7871.124 ran the fresh container journey in [CI run 31520253627](https://github.com/chris-tse/costco-chicken-tracker/actions/runs/31520253627). |
| Physical iPhone 15 Pro with current Safari | **Blocked: external device required** | No physical iPhone, Safari bridge, cloud device provider, or T3 preview automation host was available. This must be run manually against isolated seeded PostgreSQL; do not mark acceptance passed before recording the actual device/browser versions and result. |

## Operator completion checklist

1. On a physical iPhone 15 Pro/current Safari, run the approximately ten-minute journey against
   an isolated, resettable seeded PostgreSQL database. Cover Capture, reload before enrichment,
   doneness, injected enrichment failure, correction, Cancel, confirmed deletion, recency, Plan
   empty/sparse states, focus/keyboard, and overflow at 375px–430px portrait widths. Append the
   device model, iOS/Safari versions, viewport(s), date, source commit, and result.
2. Change this record to accepted only when every required row has named evidence. A missing
   physical-device result is a release blocker, not an accepted limitation.
